func (q *sqliteQueries) ListAttempts(ctx context.Context, db DBTX, arg ListAttemptsParams) ([]ListAttemptsRow, error) {
	rows, err := db.QueryContext(ctx, q.listAttempts,
		timeTextPtr(arg.CreatedAfter),
		timeTextPtr(arg.CreatedBefore),
		timeTextPtr(arg.UpdatedAfter),
		timeTextPtr(arg.UpdatedBefore),
		arg.IncludeArchived,
		arg.DeliveryID,
		arg.Scope,
		arg.PageCursor,
		arg.ResultLimit,
	)
	if err != nil {
		return nil, err
	}

	defer func() { _ = rows.Close() }()

	var items []ListAttemptsRow

	for rows.Next() {
		var i ListAttemptsRow

		if err := rows.Scan(
			&i.ID,
			&i.DeliveryID,
			&i.EndpointID,
			&i.AttemptCount,
			&i.StatusCode,
			&i.Error,
			&i.DurationMs,
			&i.CreatedAt,
			&i.LastUpdatedAt,
			&i.ArchivedAt,
			&i.FilteredCount,
			&i.TotalCount,
		); err != nil {
			return nil, err
		}

		items = append(items, i)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return items, nil
}

